"""Layer A/B persistence, review workflow and publication.

Publication rules (spec §24, ADR-0008):
* only artifacts in review_state ``approved`` can be published;
* every source unit cited by a published artifact must belong to a published
  SourceVersion (``include_sources=True`` publishes them in the same audited
  action);
* artifacts generated by the mock provider cannot be published outside
  development/test;
* publishing or unpublishing bumps the corpus version and enqueues a
  WordPress cache-purge webhook; nothing is overwritten (supersedes chain).
"""

from __future__ import annotations

import datetime as dt
from typing import Any

from sqlalchemy.engine import Connection

from .. import ids
from ..gates import GateDecision
from .core import execute, j, row, rows, scalar
from .ops import audit, bump_corpus_version, enqueue_webhook

# Closing a system-time interval must never produce an empty range, even for
# a row recorded earlier in the same transaction (now() is transaction start).
CLOSE_RECORDED = ("tstzrange(lower(recorded_during), "
                  "greatest(clock_timestamp(), lower(recorded_during) + interval '1 microsecond'), '[)')")


class PublicationError(RuntimeError):
    def __init__(self, code: str, message: str, details: Any = None):
        super().__init__(message)
        self.code = code
        self.details = details


# ------------------------------------------------------------------ claims
def ensure_claim(conn: Connection, *, case_id: str, slug: str, question: str, claim_type: str, stance: str | None,
                 title: str, claim_text: str, editorial_priority: int = 0, thesis_code: str | None = None,
                 sensitivity: list[str] | None = None, disclosure: str | None = None, valid_from: Any = None,
                 created_by: str = "system") -> tuple[str, str]:
    """Create the claim (deterministic id from slug) and its first version if
    the text changed. Returns (claim_id, claim_version_id)."""
    cid = str(ids.derived_uuid("claim", case_id, slug))
    execute(conn, """
        INSERT INTO ntk.claims (id, case_id, canonical_question, claim_type, stance, slug, thesis_code, sensitivity)
        VALUES (CAST(:id AS uuid), :case, :q, :t, :st, :slug, :code, :sens)
        ON CONFLICT (id) DO NOTHING
    """, {"id": cid, "case": case_id, "q": question, "t": claim_type, "st": stance, "slug": slug, "code": thesis_code,
          "sens": sensitivity or []})
    vid = str(ids.derived_uuid("claim_version", cid, title, claim_text, editorial_priority))
    prev = row(conn, """SELECT id FROM ntk.claim_versions WHERE claim_id = CAST(:c AS uuid) AND upper(recorded_during) IS NULL
                        ORDER BY created_at DESC LIMIT 1""", {"c": cid})
    if prev and str(prev["id"]) == vid:
        return cid, vid
    if prev:
        execute(conn, f"UPDATE ntk.claim_versions SET recorded_during = {CLOSE_RECORDED} WHERE id = :id", {"id": prev["id"]})
    execute(conn, """
        INSERT INTO ntk.claim_versions (id, claim_id, title, claim_text, editorial_priority, valid_during, supersedes_id,
            claim_type, disclosure, created_by)
        VALUES (CAST(:id AS uuid), CAST(:c AS uuid), :title, :text, :prio,
            tstzrange(coalesce(CAST(:vf AS timestamptz), now()), NULL, '[)'), :sup, :ct, :disc, :by)
        ON CONFLICT (id) DO UPDATE SET recorded_during = tstzrange(now(), NULL, '[)')
    """, {"id": vid, "c": cid, "title": title, "text": claim_text, "prio": editorial_priority, "vf": valid_from,
          "sup": prev["id"] if prev else None, "ct": claim_type, "disc": disclosure, "by": created_by})
    return cid, vid


def get_claim(conn: Connection, claim_id: str) -> dict | None:
    return row(conn, """
        SELECT c.*, v.id AS version_id, v.title, v.claim_text, v.editorial_priority, v.review_state AS version_state,
               v.disclosure, v.claim_type AS version_claim_type
        FROM ntk.claims c
        JOIN LATERAL (SELECT * FROM ntk.claim_versions v WHERE v.claim_id = c.id AND upper(v.recorded_during) IS NULL
                      ORDER BY created_at DESC LIMIT 1) v ON true
        WHERE c.id = CAST(:id AS uuid)
    """, {"id": claim_id})


def list_claims(conn: Connection) -> list[dict]:
    return rows(conn, """
        SELECT c.id, c.slug, c.thesis_code, c.canonical_question, c.claim_type, c.stance, v.title, v.editorial_priority
        FROM ntk.claims c JOIN LATERAL (SELECT * FROM ntk.claim_versions v WHERE v.claim_id = c.id
            AND upper(v.recorded_during) IS NULL ORDER BY created_at DESC LIMIT 1) v ON true
        ORDER BY v.editorial_priority DESC, c.slug
    """)


def set_editorial_priority(conn: Connection, claim_id: str, priority: int, actor: str) -> str:
    c = get_claim(conn, claim_id)
    if c is None:
        raise PublicationError("not_found", "claim not found")
    _, vid = ensure_claim(conn, case_id=c["case_id"], slug=c["slug"], question=c["canonical_question"],
                          claim_type=c["claim_type"], stance=c["stance"], title=c["title"], claim_text=c["claim_text"],
                          editorial_priority=priority, thesis_code=c["thesis_code"], sensitivity=c["sensitivity"],
                          disclosure=c["disclosure"], created_by=actor)
    return vid


def current_claim_status(conn: Connection, claim_id: str, *, as_of: Any = None, known_at: Any = None) -> dict | None:
    return row(conn, """
        SELECT status, rationale, source_unit_ids, lower(valid_during) AS valid_from, upper(valid_during) AS valid_to
        FROM ntk.claim_status_periods
        WHERE claim_id = CAST(:c AS uuid)
          AND valid_during @> coalesce(CAST(:as_of AS timestamptz), now())
          AND recorded_during @> coalesce(CAST(:known AS timestamptz), now())
        ORDER BY lower(valid_during) DESC LIMIT 1
    """, {"c": claim_id, "as_of": as_of, "known": known_at})


def record_claim_status(conn: Connection, *, claim_id: str, status: str, valid_from: Any, rationale: str | None,
                        source_unit_ids: list[str]) -> None:
    """Bi-temporal status write (spec §23.8): close the system-time of the
    current overlapping rows, re-insert their truncated history, insert new."""
    current = rows(conn, """
        SELECT * FROM ntk.claim_status_periods WHERE claim_id = CAST(:c AS uuid) AND upper(recorded_during) IS NULL
          AND valid_during && tstzrange(CAST(:vf AS timestamptz), NULL, '[)')
    """, {"c": claim_id, "vf": valid_from})
    for r in current:
        if r["status"] == status and r["valid_during"].lower is not None and r["valid_during"].lower <= _ts(valid_from):
            return  # unchanged
    for r in current:
        execute(conn, f"UPDATE ntk.claim_status_periods SET recorded_during = {CLOSE_RECORDED} WHERE id = :id",
                {"id": r["id"]})
        lower = r["valid_during"].lower
        if lower is not None and lower < _ts(valid_from):
            execute(conn, """
                INSERT INTO ntk.claim_status_periods (claim_id, status, rationale, source_unit_ids, valid_during)
                VALUES (:c, :st, :ra, :su, tstzrange(:lo, CAST(:vf AS timestamptz), '[)'))
            """, {"c": r["claim_id"], "st": r["status"], "ra": r["rationale"], "su": r["source_unit_ids"], "lo": lower,
                  "vf": valid_from})
    execute(conn, """
        INSERT INTO ntk.claim_status_periods (claim_id, status, rationale, source_unit_ids, valid_during)
        VALUES (CAST(:c AS uuid), CAST(:st AS ntk.claim_status), :ra, :su, tstzrange(CAST(:vf AS timestamptz), NULL, '[)'))
    """, {"c": claim_id, "st": status, "ra": rationale, "su": source_unit_ids, "vf": valid_from})


def _ts(v: Any) -> dt.datetime:
    if isinstance(v, dt.datetime):
        return v if v.tzinfo else v.replace(tzinfo=dt.UTC)
    return dt.datetime.fromisoformat(str(v).replace("Z", "+00:00"))


# ------------------------------------------------------------------ artifacts
def _content_hash(payload: dict) -> str:
    p = {k: v for k, v in payload.items() if k not in {"review", "as_of", "id"}}
    return ids.sha256_json(p)


def save_artifact(conn: Connection, *, artifact_id: str, artifact_type: str, object_type: str, object_id: str,
                  payload: dict, decision: GateDecision, model_run_id: str | None, verifier_run_id: str | None,
                  schema_version: str = "2.0", actor: str = "pipeline") -> tuple[str, bool]:
    """Insert an artifact version (idempotent by content hash). Opens a review
    task unless the gates rejected it."""
    content = _content_hash(payload)
    existing = row(conn, """SELECT id FROM ntk.generated_artifacts WHERE artifact_type = :t AND object_type = :ot
                            AND object_id = :oid AND content_sha256 = :h""",
                   {"t": artifact_type, "ot": object_type, "oid": object_id, "h": content})
    if existing:
        return str(existing["id"]), False
    prev = row(conn, """SELECT id FROM ntk.generated_artifacts WHERE artifact_type = :t AND object_type = :ot
                        AND object_id = :oid ORDER BY created_at DESC LIMIT 1""",
               {"t": artifact_type, "ot": object_type, "oid": object_id})
    execute(conn, """
        INSERT INTO ntk.generated_artifacts (id, artifact_type, object_type, object_id, schema_version, payload,
            review_state, model_run_id, supersedes_id, content_sha256, verifier_run_id, gate_report, risk_flags)
        VALUES (CAST(:id AS uuid), :t, :ot, :oid, :sv, CAST(:p AS jsonb), CAST(:st AS ntk.review_state),
            CAST(:mr AS uuid), :sup, :h, CAST(:vr AS uuid), CAST(:gr AS jsonb), :rf)
        ON CONFLICT (id) DO NOTHING
    """, {"id": artifact_id, "t": artifact_type, "ot": object_type, "oid": object_id, "sv": schema_version,
          "p": j(payload), "st": decision.state, "mr": model_run_id, "sup": prev["id"] if prev else None, "h": content,
          "vr": verifier_run_id, "gr": j(decision.report()), "rf": decision.risk_flags})
    cits = []
    for path, uid in _citation_paths(payload):
        cits.append({"a": artifact_id, "p": path, "u": uid})
    execute(conn, """INSERT INTO ntk.artifact_citations (artifact_id, assertion_path, source_unit_id)
                     VALUES (CAST(:a AS uuid), :p, :u) ON CONFLICT DO NOTHING""", cits)
    if decision.state != "rejected":
        open_review_task(conn, object_type="artifact", object_id=artifact_id, risk_flags=decision.risk_flags,
                         reason=f"{artifact_type} for {object_type}:{object_id} ({decision.state})")
    audit(conn, actor=actor, action="artifact.created", object_type="artifact", object_id=artifact_id,
          details={"artifact_type": artifact_type, "state": decision.state, "risk_flags": decision.risk_flags})
    return artifact_id, True


def _citation_paths(payload: dict) -> list[tuple[str, str]]:
    out: list[tuple[str, str]] = []
    for i, s in enumerate(payload.get("summary_sentences", []) or []):
        out += [(f"summary_sentences/{i}", c) for c in s["citation_ids"]]
    for key in ("support", "weakness"):
        for i, p in enumerate(payload.get(key, []) or []):
            out += [(f"{key}/{i}", c) for c in p["citation_ids"]]
    cp = payload.get("court_position")
    if cp:
        out += [("court_position", c) for c in cp["citation_ids"]]
    for i, s in enumerate(payload.get("sections", []) or []):
        out += [(f"sections/{i}", c) for c in s["citation_ids"]]
    if not out:
        out = [("citations", c["source_unit_id"]) for c in payload.get("citations", [])]
    return list(dict.fromkeys(out))


def get_artifact(conn: Connection, artifact_id: str) -> dict | None:
    return row(conn, "SELECT * FROM ntk.generated_artifacts WHERE id = CAST(:id AS uuid)", {"id": artifact_id})


def list_artifacts(conn: Connection, *, state: str | None = None, artifact_type: str | None = None, limit: int = 100) -> list[dict]:
    return rows(conn, """
        SELECT id, artifact_type, object_type, object_id, review_state, risk_flags, created_at, model_run_id,
               verifier_run_id, supersedes_id
        FROM ntk.generated_artifacts
        WHERE (CAST(:st AS text) IS NULL OR review_state = CAST(:st AS ntk.review_state))
          AND (CAST(:t AS text) IS NULL OR artifact_type = :t)
        ORDER BY created_at DESC LIMIT :lim
    """, {"st": state, "t": artifact_type, "lim": limit})


# ------------------------------------------------------------------ review
def open_review_task(conn: Connection, *, object_type: str, object_id: str, risk_flags: list[str], reason: str) -> str:
    existing = row(conn, "SELECT id FROM ntk.review_tasks WHERE object_type=:t AND object_id=:o AND status='open'",
                   {"t": object_type, "o": object_id})
    if existing:
        return str(existing["id"])
    rid = str(ids.derived_uuid("review_task", object_type, object_id,
                               scalar(conn, "SELECT count(*) FROM ntk.review_tasks WHERE object_type=:t AND object_id=:o",
                                      {"t": object_type, "o": object_id})))
    execute(conn, """INSERT INTO ntk.review_tasks (id, object_type, object_id, risk_flags, reason)
                     VALUES (CAST(:id AS uuid), :t, :o, :rf, :r)""",
            {"id": rid, "t": object_type, "o": object_id, "rf": risk_flags, "r": reason})
    return rid


def list_review_tasks(conn: Connection, *, status: str = "open", limit: int = 100) -> list[dict]:
    return rows(conn, """
        SELECT rt.*, ga.artifact_type, ga.review_state AS artifact_state
        FROM ntk.review_tasks rt
        LEFT JOIN ntk.generated_artifacts ga ON rt.object_type = 'artifact' AND ga.id::text = rt.object_id
        WHERE rt.status = :st ORDER BY rt.created_at LIMIT :lim
    """, {"st": status, "lim": limit})


_DECISION_STATE = {"approve": ("approved", "approved"), "reject": ("rejected", "rejected"),
                   "revise": ("draft", "changes_requested")}


def review_artifact(conn: Connection, *, artifact_id: str, decision: str, reviewer: str, notes: str | None,
                    request_id: str | None = None) -> dict:
    art = get_artifact(conn, artifact_id)
    if art is None:
        raise PublicationError("not_found", "artifact not found")
    if decision not in _DECISION_STATE:
        raise PublicationError("invalid_request", f"unknown decision {decision!r}")
    if art["review_state"] == "published":
        raise PublicationError("conflict", "artifact is published; unpublish it first")
    gate_state = (art.get("gate_report") or {}).get("state")
    if decision == "approve" and gate_state == "rejected":
        raise PublicationError("citation_gate_failed", "artifact failed automatic gates and cannot be approved",
                               art.get("gate_report"))
    new_state, task_status = _DECISION_STATE[decision]
    execute(conn, """UPDATE ntk.generated_artifacts SET review_state = CAST(:s AS ntk.review_state), updated_at = now()
                     WHERE id = CAST(:id AS uuid)""", {"s": new_state, "id": artifact_id})
    execute(conn, """
        UPDATE ntk.review_tasks SET status = :ts, decision = :d, decided_by = :by, notes = :n, completed_at = now(),
            updated_at = now()
        WHERE object_type = 'artifact' AND object_id = :id AND status = 'open'
    """, {"ts": task_status, "d": decision, "by": reviewer, "n": notes, "id": artifact_id})
    if decision == "approve" and art["artifact_type"] == "claim_card":
        # judicial statements and evidence cited by an approved card are human-approved with it
        execute(conn, """UPDATE ntk.judicial_statements SET review_state = 'approved', reviewed_by = :by, reviewed_at = now()
                         WHERE source_unit_id IN (SELECT source_unit_id FROM ntk.artifact_citations
                                                  WHERE artifact_id = CAST(:id AS uuid) AND assertion_path = 'court_position')""",
                {"by": reviewer, "id": artifact_id})
    audit(conn, actor=reviewer, action=f"artifact.review.{decision}", object_type="artifact", object_id=artifact_id,
          request_id=request_id, details={"notes": notes, "previous_state": art["review_state"]})
    return {"artifact_id": artifact_id, "review_state": new_state}


def review_object(conn: Connection, *, object_type: str, object_id: str, decision: str, reviewer: str,
                  notes: str | None, request_id: str | None = None) -> dict:
    """Review for non-artifact objects: qa_exchange, judicial_statement."""
    table = {"qa_exchange": "ntk.qa_exchanges", "judicial_statement": "ntk.judicial_statements"}.get(object_type)
    if table is None:
        raise PublicationError("invalid_request", f"unsupported object_type {object_type!r}")
    new_state = _DECISION_STATE[decision][0]
    key = "id" if object_type == "qa_exchange" else "id"
    cast = "" if object_type == "qa_exchange" else "CAST(:id AS uuid)"
    where = f"{key} = {cast or ':id'}"
    n = execute(conn, f"UPDATE {table} SET review_state = CAST(:s AS ntk.review_state) WHERE {where}",
                {"s": new_state, "id": object_id})
    if n == 0:
        raise PublicationError("not_found", f"{object_type} not found")
    execute(conn, """UPDATE ntk.review_tasks SET status = :ts, decision = :d, decided_by = :by, notes = :n,
                     completed_at = now() WHERE object_type = :ot AND object_id = :id AND status = 'open'""",
            {"ts": _DECISION_STATE[decision][1], "d": decision, "by": reviewer, "n": notes, "ot": object_type, "id": object_id})
    audit(conn, actor=reviewer, action=f"{object_type}.review.{decision}", object_type=object_type, object_id=object_id,
          request_id=request_id, details={"notes": notes})
    return {"object_type": object_type, "object_id": object_id, "review_state": new_state}


# ------------------------------------------------------------------ publication
def publish_source_version(conn: Connection, source_version_id: str, *, actor: str, request_id: str | None = None,
                           bump: bool = True) -> str | None:
    n = execute(conn, """UPDATE ntk.source_versions SET publication_state = 'published', publication_changed_at = now(),
                         publication_changed_by = :a WHERE id = :id AND publication_state <> 'published'""",
                {"id": source_version_id, "a": actor})
    if n == 0:
        if scalar(conn, "SELECT count(*) FROM ntk.source_versions WHERE id = :id", {"id": source_version_id}) == 0:
            raise PublicationError("not_found", "source version not found")
        return None
    audit(conn, actor=actor, action="source_version.publish", object_type="source_version", object_id=source_version_id,
          request_id=request_id)
    if bump:
        cv = bump_corpus_version(conn, reason=f"publish source {source_version_id}", actor=actor)
        enqueue_webhook(conn, "source_version.published", {"source_version_id": source_version_id, "corpus_version": cv})
        return cv
    return None


def withdraw_source_version(conn: Connection, source_version_id: str, *, actor: str, reason: str,
                            request_id: str | None = None) -> str:
    dependants = scalar(conn, """
        SELECT count(*) FROM ntk.artifact_citations ac JOIN ntk.source_units su ON su.id = ac.source_unit_id
        JOIN ntk.generated_artifacts ga ON ga.id = ac.artifact_id
        WHERE su.source_version_id = :sv AND ga.review_state = 'published'
    """, {"sv": source_version_id})
    if dependants:
        raise PublicationError("conflict", f"{dependants} published citations depend on this source; unpublish them first")
    execute(conn, """UPDATE ntk.source_versions SET publication_state = 'withdrawn', publication_changed_at = now(),
                     publication_changed_by = :a WHERE id = :id""", {"id": source_version_id, "a": actor})
    audit(conn, actor=actor, action="source_version.withdraw", object_type="source_version", object_id=source_version_id,
          request_id=request_id, details={"reason": reason})
    cv = bump_corpus_version(conn, reason=f"withdraw source {source_version_id}", actor=actor)
    enqueue_webhook(conn, "source_version.withdrawn", {"source_version_id": source_version_id, "corpus_version": cv})
    return cv


def publish_artifact(conn: Connection, *, artifact_id: str, actor: str, env: str, public_base_url: str,
                     include_sources: bool = False, request_id: str | None = None) -> dict:
    art = get_artifact(conn, artifact_id)
    if art is None:
        raise PublicationError("not_found", "artifact not found")
    if art["review_state"] == "published":
        pub = row(conn, "SELECT * FROM ntk.publications WHERE artifact_id = CAST(:id AS uuid) AND unpublished_at IS NULL",
                  {"id": artifact_id})
        return {"artifact_id": artifact_id, "review_state": "published", "publication": pub, "already": True}
    if art["review_state"] != "approved":
        raise PublicationError("review_required", f"artifact is {art['review_state']}; it must be approved before publishing")
    fams = set(scalar(conn, """SELECT array_agg(DISTINCT model_family) FROM ntk.model_runs
                               WHERE id IN (CAST(:a AS uuid), CAST(:b AS uuid))""",
                      {"a": str(art["model_run_id"]) if art["model_run_id"] else None,
                       "b": str(art["verifier_run_id"]) if art["verifier_run_id"] else None}) or [])
    if "mock" in fams and env not in {"development", "test"}:
        raise PublicationError("review_required", "artifact was generated by the mock provider; regenerate with a real model")
    unpublished_sources = rows(conn, """
        SELECT DISTINCT sv.id FROM ntk.artifact_citations ac
        JOIN ntk.source_units su ON su.id = ac.source_unit_id
        JOIN ntk.source_versions sv ON sv.id = su.source_version_id
        WHERE ac.artifact_id = CAST(:id AS uuid) AND sv.publication_state <> 'published'
    """, {"id": artifact_id})
    if unpublished_sources:
        if not include_sources:
            raise PublicationError("unpublished_object", "cited sources are not published",
                                   {"source_version_ids": [r["id"] for r in unpublished_sources]})
        for r in unpublished_sources:
            publish_source_version(conn, r["id"], actor=actor, request_id=request_id, bump=False)
    # supersede the previously published artifact for the same object
    prev = rows(conn, """
        SELECT ga.id FROM ntk.generated_artifacts ga JOIN ntk.publications p ON p.artifact_id = ga.id AND p.unpublished_at IS NULL
        WHERE ga.artifact_type = :t AND ga.object_type = :ot AND ga.object_id = :oid AND ga.id <> CAST(:id AS uuid)
    """, {"t": art["artifact_type"], "ot": art["object_type"], "oid": art["object_id"], "id": artifact_id})
    for p in prev:
        execute(conn, "UPDATE ntk.publications SET unpublished_at = now() WHERE artifact_id = :a AND unpublished_at IS NULL",
                {"a": p["id"]})
        execute(conn, "UPDATE ntk.generated_artifacts SET review_state = 'superseded', updated_at = now() WHERE id = :a",
                {"a": p["id"]})
    cv = bump_corpus_version(conn, reason=f"publish artifact {artifact_id}", actor=actor)
    slug = f"{art['artifact_type']}-{art['object_type']}-{art['object_id']}".replace(":", "-")[:200]
    canonical = f"{public_base_url.rstrip('/')}/v2/{_public_path(art)}"
    pub_id = str(ids.derived_uuid("publication", artifact_id, cv))
    execute(conn, """
        INSERT INTO ntk.publications (id, artifact_id, slug, canonical_url, knowledge_version)
        VALUES (CAST(:id AS uuid), CAST(:a AS uuid), :slug, :url, :kv)
    """, {"id": pub_id, "a": artifact_id, "slug": slug, "url": canonical, "kv": cv})
    execute(conn, "UPDATE ntk.generated_artifacts SET review_state = 'published', updated_at = now() WHERE id = CAST(:id AS uuid)",
            {"id": artifact_id})
    if art["artifact_type"] == "claim_card":
        payload = art["payload"]
        record_claim_status(conn, claim_id=art["object_id"], status=payload["status"], valid_from=payload["as_of"],
                            rationale=payload.get("answer_short"),
                            source_unit_ids=[c["source_unit_id"] for c in payload.get("citations", [])])
        execute(conn, """UPDATE ntk.evidence_items SET review_state = 'published'
                         WHERE id IN (SELECT evidence_id FROM ntk.claim_evidence WHERE claim_id = CAST(:c AS uuid))""",
                {"c": art["object_id"]})
    audit(conn, actor=actor, action="artifact.publish", object_type="artifact", object_id=artifact_id,
          request_id=request_id, details={"corpus_version": cv, "superseded": [str(p["id"]) for p in prev],
                                          "sources_published": [r["id"] for r in unpublished_sources]})
    enqueue_webhook(conn, "artifact.published", {"artifact_id": artifact_id, "artifact_type": art["artifact_type"],
                                                 "object_type": art["object_type"], "object_id": art["object_id"],
                                                 "corpus_version": cv})
    return {"artifact_id": artifact_id, "review_state": "published", "corpus_version": cv,
            "publication": {"id": pub_id, "slug": slug, "canonical_url": canonical, "knowledge_version": cv}}


def unpublish_artifact(conn: Connection, *, artifact_id: str, actor: str, reason: str, request_id: str | None = None) -> dict:
    art = get_artifact(conn, artifact_id)
    if art is None:
        raise PublicationError("not_found", "artifact not found")
    if art["review_state"] != "published":
        raise PublicationError("conflict", f"artifact is {art['review_state']}, not published")
    execute(conn, "UPDATE ntk.publications SET unpublished_at = now() WHERE artifact_id = CAST(:a AS uuid) AND unpublished_at IS NULL",
            {"a": artifact_id})
    execute(conn, "UPDATE ntk.generated_artifacts SET review_state = 'approved', updated_at = now() WHERE id = CAST(:a AS uuid)",
            {"a": artifact_id})
    cv = bump_corpus_version(conn, reason=f"unpublish artifact {artifact_id}: {reason}", actor=actor)
    audit(conn, actor=actor, action="artifact.unpublish", object_type="artifact", object_id=artifact_id,
          request_id=request_id, details={"reason": reason, "corpus_version": cv})
    enqueue_webhook(conn, "artifact.unpublished", {"artifact_id": artifact_id, "artifact_type": art["artifact_type"],
                                                   "object_type": art["object_type"], "object_id": art["object_id"],
                                                   "corpus_version": cv})
    return {"artifact_id": artifact_id, "review_state": "approved", "corpus_version": cv}


def _public_path(art: dict) -> str:
    t = art["artifact_type"]
    if t == "claim_card":
        return f"claims/{art['object_id']}"
    if t == "summary" and art["object_type"] == "hearing":
        return f"hearings/{art['object_id']}"
    return f"artifacts/{art['id']}"


# ------------------------------------------------------------------ layer A / B rows
def save_layer_a(conn: Connection, *, object_type: str, object_key: str, version_id: str, payload: dict,
                 source_unit_ids: list[str], model_run_id: str | None, review_state: str) -> None:
    oid = str(ids.derived_uuid("layer_a_object", object_type, object_key))
    execute(conn, """INSERT INTO ntk.layer_a_objects (id, object_type, object_key) VALUES (CAST(:id AS uuid), :t, :k)
                     ON CONFLICT DO NOTHING""", {"id": oid, "t": object_type, "k": object_key})
    prev = row(conn, "SELECT id FROM ntk.layer_a_versions WHERE object_id = CAST(:o AS uuid) ORDER BY created_at DESC LIMIT 1",
               {"o": oid})
    execute(conn, """
        INSERT INTO ntk.layer_a_versions (id, object_id, schema_version, short_summary, long_summary, payload,
            source_unit_ids, review_state, model_run_id, supersedes_id)
        VALUES (CAST(:id AS uuid), CAST(:o AS uuid), '2.0', :short, :long, CAST(:p AS jsonb), :su,
            CAST(:st AS ntk.review_state), CAST(:mr AS uuid), :sup)
        ON CONFLICT (id) DO NOTHING
    """, {"id": version_id, "o": oid, "short": payload.get("summary", "")[:2000], "long": payload.get("summary"),
          "p": j(payload), "su": source_unit_ids, "st": review_state, "mr": model_run_id,
          "sup": prev["id"] if prev and str(prev["id"]) != version_id else None})


def save_evidence_from_bundle(conn: Connection, *, case_id: str, claim_id: str, bundle: dict, review_state: str,
                              model_run_id: str | None) -> int:
    n = 0
    for key in ("support", "weakness"):
        for p in bundle.get(key, []):
            execute(conn, """
                INSERT INTO ntk.evidence_items (id, case_id, evidence_type, summary, court_record_status, review_state, model_run_id)
                VALUES (CAST(:id AS uuid), :case, 'testimony', :s, CAST(:crs AS ntk.court_record_status),
                    CAST(:st AS ntk.review_state), CAST(:mr AS uuid))
                ON CONFLICT (id) DO NOTHING
            """, {"id": p["evidence_id"], "case": case_id, "s": p["summary"], "crs": p["court_record_status"],
                  "st": review_state, "mr": model_run_id})
            execute(conn, """INSERT INTO ntk.evidence_sources (evidence_id, source_unit_id, relation)
                             VALUES (CAST(:e AS uuid), :u, 'quotes') ON CONFLICT DO NOTHING""",
                    [{"e": p["evidence_id"], "u": u} for u in p["citation_ids"]])
            execute(conn, """
                INSERT INTO ntk.claim_evidence (claim_id, evidence_id, direction, rationale, review_state)
                VALUES (CAST(:c AS uuid), CAST(:e AS uuid), CAST(:d AS ntk.evidence_direction), :r, CAST(:st AS ntk.review_state))
                ON CONFLICT DO NOTHING
            """, {"c": claim_id, "e": p["evidence_id"], "d": p["direction"], "r": p["summary"][:500], "st": review_state})
            n += 1
    return n


def save_judicial_statement(conn: Connection, *, source_unit_id: str, level: str, summary: str, confidence: float,
                            related_claim_ids: list[str], model_run_id: str | None, statement_date: str | None) -> str:
    jid = str(ids.derived_uuid("judicial_statement", source_unit_id, level))
    execute(conn, """
        INSERT INTO ntk.judicial_statements (id, source_unit_id, level, summary, related_claim_ids, classifier_confidence,
            classifier_model_run_id, statement_date, candidate_source)
        VALUES (CAST(:id AS uuid), :u, CAST(:l AS ntk.judicial_level), :s, CAST(:rc AS uuid[]), :c, CAST(:mr AS uuid),
            CAST(:d AS date), 'classifier')
        ON CONFLICT (source_unit_id, level) DO UPDATE SET
            related_claim_ids = (SELECT array_agg(DISTINCT x) FROM unnest(ntk.judicial_statements.related_claim_ids || EXCLUDED.related_claim_ids) x)
    """, {"id": jid, "u": source_unit_id, "l": level, "s": summary[:1000], "rc": related_claim_ids, "c": confidence,
          "mr": model_run_id, "d": statement_date})
    open_review_task(conn, object_type="judicial_statement", object_id=jid, risk_flags=["judicial_classification"],
                     reason=f"classify judicial statement at {source_unit_id} as {level}")
    return jid


def judicial_levels_for(conn: Connection, unit_ids: list[str]) -> dict[str, tuple[str, bool]]:
    out: dict[str, tuple[str, bool]] = {}
    for r in rows(conn, """SELECT source_unit_id, level, review_state FROM ntk.judicial_statements
                           WHERE source_unit_id = ANY(:ids) ORDER BY level DESC""", {"ids": unit_ids}):
        approved = r["review_state"] in {"approved", "published"}
        cur = out.get(r["source_unit_id"])
        if cur is None or (approved and not cur[1]):
            out[r["source_unit_id"]] = (r["level"], approved)
    return out


def add_case_event(conn: Connection, *, case_id: str, event_type: str, occurred_at: str, title: str,
                   description: str | None, outcome: str | None = None, source_unit_ids: list[str] | None = None,
                   external_sources: list[dict] | None = None, review_state: str = "draft", actor: str = "system") -> str:
    eid = str(ids.derived_uuid("case_event", case_id, event_type, occurred_at, title))
    execute(conn, """
        INSERT INTO ntk.case_events (id, case_id, event_type, occurred_at, outcome, title, description, source_unit_ids,
            valid_during, review_state, external_sources, created_by)
        VALUES (CAST(:id AS uuid), :case, :et, CAST(:at AS timestamptz), CAST(:oc AS ntk.outcome_type), :t, :d, :su,
            tstzrange(CAST(:at AS timestamptz), NULL, '[)'), CAST(:st AS ntk.review_state), CAST(:ex AS jsonb), :by)
        ON CONFLICT (id) DO NOTHING
    """, {"id": eid, "case": case_id, "et": event_type, "at": occurred_at, "oc": outcome, "t": title, "d": description,
          "su": source_unit_ids or [], "st": review_state, "ex": j(external_sources or []), "by": actor})
    return eid
